import{_ as l,a0 as d,w as n,s as p,ao as c,I as o,x as t,a1 as s,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"终端基础：Linux 终端中的目录切换 | LCTT x X-CMD","titleTemplate":false,"description":"终端基础：Linux 终端中的目录切换 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"终端基础：Linux 终端中的目录切换 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"终端基础：Linux 终端中的目录切换 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20230213.2 ⭐️ Terminal Basics Series 1 Changing Directories in Linux Terminal","title":"终端基础：Linux 终端中的目录切换","tag":"202310","desc":""},"relativePath":"202310/20230213.2 ⭐️ Terminal Basics Series 1 Changing Directories in Linux Terminal.md","filePath":"[post].md"}'),r={name:"202310/20230213.2 ⭐️ Terminal Basics Series 1 Changing Directories in Linux Terminal.md"};function h(u,e,g,m,b,k){const i=d("Link");return n(),p("div",null,[e[15]||(e[15]=c(`<h1 id="终端基础-linux-终端中的目录切换" tabindex="-1">终端基础：Linux 终端中的目录切换 <a class="header-anchor" href="#终端基础-linux-终端中的目录切换" aria-label="Permalink to “终端基础：Linux 终端中的目录切换”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/21/062234mz9zymqc6om5924m.jpg" alt=""></p><blockquote><p>本篇文章作为终端基础教程系列的一部分，介绍如何在 Linux 命令行中，利用绝对路径和相对路径实现目录切换。</p></blockquote><p>Linux 的 <code>cd</code> 命令让你可以轻松切换文件夹（即目录）。只需提供你要切换到的文件夹路径即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd path_to_directory</span></span></code></pre></div><p>然而对于 Linux 新人来说，可能会在路径的指定上有所困扰。</p><p>首先，让我们解决这个问题。</p><h3 id="理解-linux-中的路径" tabindex="-1">理解 Linux 中的路径 <a class="header-anchor" href="#理解-linux-中的路径" aria-label="Permalink to “理解 Linux 中的路径”">​</a></h3><p>在 Linux 文件系统中，路径是用来追踪文件位置的信息。所有的路径都从根目录开始，然后向下延伸。</p><p>你可以通过下面的方式查看当前所在的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pwd</span></span></code></pre></div><p>结果可能是类似于 <code>/home/username</code> 的输出。注意，这里的 <code>username</code> 将会是你自己的用户名。</p><p>你可以注意到，路径是由 <code>/</code> 符号和目录名组成的。比如路径 <code>/home/abhishek/scripts</code>， 表示 <code>scripts</code> 是在文件夹 <code>abhishek</code> 之内，而文件夹 <code>abhishek</code> 在 <code>home</code> 文件夹之内。要注意，第一个 &#39;/&#39; 是指根目录（即文件系统的开始处），后面的 &#39;/&#39; 则作为目录的分隔符。</p><p><img src="https://itsfoss.com/content/images/2023/02/path-linux.webp" alt="Path in Linux"></p><blockquote><p>🖥️ 在终端中键入 <code>ls /</code>，然后按回车。你将会看到根目录下的所有内容，试试看！</p></blockquote><p>接下来，让我们学习两种常见的路径指定方式：绝对路径和相对路径。</p><p><strong>绝对路径</strong>：这种路径从根开始，然后一直扩展到你需要的位置。如果一个路径是以 <code>/</code> 开头，那就说明它是一个绝对路径。</p><p><strong>相对路径</strong>：这是相对于你文件系统中当前位置的路径。如果我当前位置在 <code>/home/abhishek</code>，并且我需要去 <code>/home/abhishek/Documents</code>， 我只需要简单地切换到 <code>Documents</code>，而不需要指定整个绝对路径 <code>/home/abhishek/Documents</code>。</p><p>在我演示这两种路径的区别之前，有必要先熟悉两个特殊的目录标识：</p><ul><li><code>.</code> （单点）表示当前目录。</li><li><code>..</code> （双点）表示上一级目录，也就是当前目录的母目录。</li></ul><p>这里有一张图形化的表示。</p><p><img src="https://itsfoss.com/content/images/2023/02/absolute-and-relative-path.png" alt="Absolute path vs relative path"></p><h3 id="利用-cd-命令变更目录" tabindex="-1">利用 cd 命令变更目录 <a class="header-anchor" href="#利用-cd-命令变更目录" aria-label="Permalink to “利用 cd 命令变更目录”">​</a></h3><p>在你已对路径概念有所了解之后，我们来了解如何切换目录。</p><blockquote><p>🖥️ 如果你<strong>仅键入 <code>cd</code> 并按回车键</strong>，无论当前位置在哪，系统都会将你带回主目录。试一试吧。</p></blockquote><p>敲入以下命令，你就能看到主目录里的所有文件夹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls</span></span></code></pre></div><p>这是我看到的情况：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@ituxedo:~$ ls</span></span>
<span class="line"><span>Desktop    Downloads  Pictures  Templates  VirtualBoxVMs</span></span>
<span class="line"><span>Documents  Music      Public    Videos</span></span></code></pre></div><p>你的情况可能与此类似，但未必完全一样。</p><p>假如你希望跳转到 <code>Documents</code> 文件夹。由于它就在当前目录下，这里使用相对路径会比较方便：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd Documents</span></span></code></pre></div><blockquote><p>💡 注意，大部分 Linux 发行版预设的终端模拟器会在提示符本身显示出当前所在的位置。因此你不必频繁使用 <code>pwd</code> 指令来确认自己的位置。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/02/linux-terminal-prompt.png" alt="Most Linux terminal prompts show the current location"></p><p>假如你希望切换到位于主目录里的 <code>Templates</code> 文件夹。</p><p>你可以使用相对路径 <code>../Templates</code>（<code>..</code> 会让你返回到上层目录，即 <code>/home/username</code>，然后你就可以进入 <code>Templates</code> 文件夹了）。</p><p>但这次我们尝试使用绝对路径。请把下面的 <code>abhishek</code> 替换成你的用户名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /home/abhishek/Templates</span></span></code></pre></div><p>此刻你已经在 <code>Templates</code> 文件夹里了。如何前往 <code>Downloads</code> 文件夹呢？这次我们再使用相对路径：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ../Downloads</span></span></code></pre></div><p>下面的图片会回顾一下你刚才学到的所有或有关目录切换的范例。</p><p><img src="https://itsfoss.com/content/images/2023/02/cd-command-example.svg" alt="cd command example"></p><blockquote><p>💡 别忘了你还可以使用终端的 <code>tab</code> 键自动补全功能。只需要键入命令或者文件夹名称的前几个字母，然后敲击 <code>tab</code> 键，系统就会尝试自动地补全命令或文件夹名称，或者给你显示出所有可能的选项。</p></blockquote><h3 id="故障解决" tabindex="-1">故障解决 <a class="header-anchor" href="#故障解决" aria-label="Permalink to “故障解决”">​</a></h3><p>在 Linux 终端操作切换目录的过程中，你可能会遇到一些常见的错误。</p><h4 id="文件或目录不存在" tabindex="-1">文件或目录不存在 <a class="header-anchor" href="#文件或目录不存在" aria-label="Permalink to “文件或目录不存在”">​</a></h4><p>如果在你尝试切换目录时，出现类似下面的错误信息：</p><blockquote><p>bash: cd: directory_name: No such file or directory</p></blockquote><p>那么你可能在路径或目录名称上犯了误解。这里有几点你需要注意的：</p><ul><li>请确定你输入的目录名中没有拼写错误。</li><li>Linux 系统对大小写敏感，因此，<code>Downloads</code> 和 <code>downloads</code> 会被识别为不同的目录。</li><li>你可能未正确指定路径。可能你所在的位置与你预期的不同？或者你遗漏了绝对路径中的开头的 <code>/</code> 字符？</li></ul><p><img src="https://itsfoss.com/content/images/2023/02/common-errors-with-cd.png" alt="Common examples of &quot;no such file or directory&quot; error"></p><h4 id="非目录错误" tabindex="-1">非目录错误 <a class="header-anchor" href="#非目录错误" aria-label="Permalink to “非目录错误”">​</a></h4><p>如果你看到像下面这样的错误提示：</p><blockquote><p>bash: cd: filename: Not a directory</p></blockquote><p>这表示你尝试使用 <code>cd</code> 命令对一个文件进行操作，而不是一个目录（文件夹）。很明显，你不能像进入文件夹那样“进入”一个文件，因此会出现这样的错误。</p><p><img src="https://itsfoss.com/content/images/2023/02/not-a-directory-error-linux.png" alt="Not a directory error with the cd command"></p><h4 id="参数过多" tabindex="-1">参数过多 <a class="header-anchor" href="#参数过多" aria-label="Permalink to “参数过多”">​</a></h4><p>这是 Linux 新手常犯的另一个错误：</p><blockquote><p>bash: cd: too many arguments</p></blockquote><p><code>cd</code> 命令只接受一个参数。也就是说，你只能对命令指定一个目录。</p><p>如果你指定了超过一个的参数，或者在路径中误加了空格，你就会看到这个错误。</p><p><img src="https://itsfoss.com/content/images/2023/02/too-many-arguments.png" alt="Too many arguments error in Linux terminal"></p><blockquote><p>🏋🏻 如果你输入 <code>cd -</code>，它将会把你带到前一个目录。当你在两个相隔较远的地方切换时非常方便，可以避免再次输入长路径。</p></blockquote><h3 id="特殊目录符号" tabindex="-1">特殊目录符号 <a class="header-anchor" href="#特殊目录符号" aria-label="Permalink to “特殊目录符号”">​</a></h3><p>在结束这个教程之前，我想快速告诉你关于特殊符号 <code>~</code>。在 Linux 中，<code>~</code> 是用户主目录的捷径。</p><p>如果用户 <code>abhi</code> 运行它，<code>~</code> 就会代表 <code>/home/abhi</code>，如果用户 <code>prakash</code> 运行，<code>~</code> 就意味着 <code>/home/prakash</code>。</p><p>总结一下你在这个基础教程系列中学到的所有特殊目录标识：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">符号</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.</code></td><td style="text-align:left;">当前目录</td></tr><tr><td style="text-align:left;"><code>..</code></td><td style="text-align:left;">上级目录</td></tr><tr><td style="text-align:left;"><code>~</code></td><td style="text-align:left;">主目录</td></tr><tr><td style="text-align:left;"><code>-</code></td><td style="text-align:left;">前一个目录</td></tr></tbody></table></div><h3 id="测试你的知识" tabindex="-1">测试你的知识 <a class="header-anchor" href="#测试你的知识" aria-label="Permalink to “测试你的知识”">​</a></h3><p>下面是一些简单的练习，用来测试你刚刚学到的关于路径和 <code>cd</code> 命令的知识。</p><p>移动到你的主目录，并使用这个命令创建一个嵌套的目录结构：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p sample/dir1/dir2/dir3</span></span></code></pre></div><p>然后，一步步来试试这个：</p><ul><li>使用绝对路径或相对路径进入 <code>dir3</code></li><li>使用相对路径移动到 <code>dir1</code></li><li>使用你能想象到的最短路径进入 <code>dir2</code></li><li>使用绝对路径切换到 <code>sample</code> 目录</li><li>返回你的主目录</li></ul><blockquote><p>🔑 想知道你是否全都做对了吗？欢迎分享你的答案。</p></blockquote><p>现在你知道如何切换目录，是不是应该学习一下如何创建它们呢？</p><p>我强烈推荐你阅读这篇文章，了解一些关于终端和命令的小技巧。</p><p>如果你想了解 Linux 命令行的基础知识，记得关注我们的 Linux 终端基础系列教程的更多章节。</p><hr>`,79)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),s(i,{href:"https://itsfoss.com/change-directories/"},{default:a(()=>[...e[0]||(e[0]=[t("https://itsfoss.com/change-directories/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),s(i,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>[...e[2]||(e[2]=[t("Abhishek Prakash",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),s(i,{href:"https://github.com/lkxed/"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),s(i,{href:"https://linux.cn/lctt/ChatGPT"},{default:a(()=>[...e[4]||(e[4]=[t("ChatGPT",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const T=l(r,[["render",h]]);export{y as __pageData,T as default};
